using System;using System.IO;using UnityEngine;using UnityEngine.UI;using UnityEditor;using IdleIntelligence.Runtime;
namespace IdleIntelligence.Editor {
 public static class BuildForgeSequence {
  const string Root="Assets/IdleIntelligence/";const string Fx="Assets/IdleIntelligence/Resources/PixelUI/";
  static void Place(RectTransform r,Vector2 anchor,Vector2 size){r.anchorMin=r.anchorMax=anchor;r.pivot=new Vector2(.5f,.5f);r.anchoredPosition=Vector2.zero;r.sizeDelta=size;}
  static Sprite Frame(int frame){var tex=new Texture2D(48,48,TextureFormat.RGBA32,false);tex.filterMode=FilterMode.Point;tex.SetPixels(new Color[48*48]);
   // Explicit stepped lightning silhouette and four unequal shard lobes; no circular glow.
   var silhouette=new Vector2[]{new Vector2(0,21),new Vector2(3,6),new Vector2(12,11),new Vector2(6,2),new Vector2(21,0),new Vector2(6,-3),new Vector2(10,-13),new Vector2(2,-6),new Vector2(0,-21),new Vector2(-3,-6),new Vector2(-14,-10),new Vector2(-6,-2),new Vector2(-21,0),new Vector2(-5,3),new Vector2(-10,14),new Vector2(-2,6)};
   bool Inside(Vector2 point){bool inside=false;for(int i=0,j=silhouette.Length-1;i<silhouette.Length;j=i++){var a=silhouette[i];var b=silhouette[j];if((a.y>point.y)!=(b.y>point.y)&&point.x<(b.x-a.x)*(point.y-a.y)/(b.y-a.y)+a.x)inside=!inside;}return inside;}
   for(int y=0;y<48;y++)for(int x=0;x<48;x++){float dx=x-24,dy=y-24;bool lit=false;if(frame<4){float scale=new[]{.28f,.62f,1f,.8f}[frame];lit=Inside(new Vector2(dx,dy)/scale);}else{float radius=9+(frame-4)*4;var directions=new[]{new Vector2(1,.2f),new Vector2(-1,-.3f),new Vector2(.15f,1),new Vector2(-.3f,-1),new Vector2(.75f,.8f),new Vector2(-.8f,.7f),new Vector2(.6f,-.9f)};for(int i=0;i<directions.Length;i++){var offset=new Vector2(dx,dy)-directions[i]*radius;float size=i%3==0?2.4f:1.4f;if(Math.Abs(offset.x)+Math.Abs(offset.y)<size)lit=true;}}if(lit)tex.SetPixel(x,y,Color.white);}
   tex.Apply();string path=Fx+"impact-"+frame+".asset";var old=AssetDatabase.LoadAssetAtPath<Texture2D>(path);if(old==null)AssetDatabase.CreateAsset(tex,path);else{EditorUtility.CopySerialized(tex,old);UnityEngine.Object.DestroyImmediate(tex);tex=old;}var sprite=Sprite.Create(tex,new Rect(0,0,48,48),new Vector2(.5f,.5f),100,0,SpriteMeshType.FullRect);string sp=Fx+"impact-sprite-"+frame+".asset";var previous=AssetDatabase.LoadAssetAtPath<Sprite>(sp);if(previous==null){AssetDatabase.CreateAsset(sprite,sp);return sprite;}EditorUtility.CopySerialized(sprite,previous);UnityEngine.Object.DestroyImmediate(sprite);return previous;
  }
  public static void Build(){var frames=new Sprite[8];for(int i=0;i<8;i++)frames[i]=Frame(i);var root=WorkshopUIFactory.Node("ForgeSequence",null);var sequence=root.AddComponent<ForgeSequence>();sequence.ImpactFrames=frames;var chargeTexture=new Texture2D(48,12,TextureFormat.RGBA32,false);chargeTexture.filterMode=FilterMode.Point;chargeTexture.SetPixels(new Color[48*12]);for(int x=2;x<46;x++){int y=x<13?5:x<19?5+(x-13)/2:x<26?8-(x-19):x<34?2+(x-26)/2:6;chargeTexture.SetPixel(x,Mathf.Clamp(y,1,10),Color.white);}chargeTexture.Apply();string cp=Fx+"energy-fork.asset";var oldCharge=AssetDatabase.LoadAssetAtPath<Texture2D>(cp);if(oldCharge==null)AssetDatabase.CreateAsset(chargeTexture,cp);else{EditorUtility.CopySerialized(chargeTexture,oldCharge);UnityEngine.Object.DestroyImmediate(chargeTexture);chargeTexture=oldCharge;}var cs=Sprite.Create(chargeTexture,new Rect(0,0,48,12),new Vector2(.5f,.5f),100,0,SpriteMeshType.FullRect);string csp=Fx+"energy-fork-sprite.asset";var oldSprite=AssetDatabase.LoadAssetAtPath<Sprite>(csp);if(oldSprite==null){AssetDatabase.CreateAsset(cs,csp);sequence.ChargeSprite=cs;}else{EditorUtility.CopySerialized(cs,oldSprite);UnityEngine.Object.DestroyImmediate(cs);sequence.ChargeSprite=oldSprite;}var portrait=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"Prefabs/ItemPortrait.prefab").GetComponent<ItemPortrait>();
   var shade=WorkshopUIFactory.Node("WorkshopCurtain",root.transform,typeof(Image)).GetComponent<Image>();WorkshopUIFactory.Fill(shade.rectTransform);shade.raycastTarget=false;sequence.Shade=shade;sequence.Sources=new ItemPortrait[3];sequence.Conduits=new Image[3];for(int i=0;i<3;i++){var line=WorkshopUIFactory.Node("EnergyFork"+i,root.transform,typeof(Image)).GetComponent<Image>();Place(line.rectTransform,new Vector2(.5f,.5f),new Vector2(64,22));line.color=Color.clear;sequence.Conduits[i]=line;var p=UnityEngine.Object.Instantiate(portrait,root.transform);p.name="FusionSource"+i;p.ShowLevel=false;Place((RectTransform)p.transform,new Vector2(.5f,.5f),new Vector2(94,94));((RectTransform)p.transform).anchoredPosition=new Vector2((i-1)*104,80);sequence.Sources[i]=p;}
   var hero=UnityEngine.Object.Instantiate(portrait,root.transform);hero.name="FusionHero";hero.ShowLevel=false;Place((RectTransform)hero.transform,new Vector2(.5f,.5f),new Vector2(176,176));((RectTransform)hero.transform).anchoredPosition=new Vector2(0,-3);sequence.Hero=hero;
   var impact=WorkshopUIFactory.Node("FacetedCollision",root.transform,typeof(Image)).GetComponent<Image>();Place(impact.rectTransform,new Vector2(.5f,.5f),new Vector2(144,144));impact.color=Color.clear;sequence.Impact=impact;
   Text Label(string name,int size,float y,float height){var t=WorkshopUIFactory.Label(name,root.transform,"",size);UnityEngine.Object.DestroyImmediate(t.GetComponent<LayoutElement>());Place(t.rectTransform,new Vector2(.5f,0),new Vector2(330,height));t.rectTransform.anchoredPosition=new Vector2(0,y);t.alignment=TextAnchor.MiddleCenter;t.resizeTextForBestFit=true;t.resizeTextMinSize=size-2;t.resizeTextMaxSize=size;return t;}
   sequence.Title=Label("SavedResultName",18,58,28);sequence.Title.font=GameTheme.Bold;sequence.Rarity=Label("SavedRarityLevel",12,36,20);sequence.Improvement=Label("ActualImprovement",13,15,24);PrefabUtility.SaveAsPrefabAsset(root,Fx+"ForgeSequence.prefab");UnityEngine.Object.DestroyImmediate(root);
   var forge=PrefabUtility.LoadPrefabContents(Root+"Prefabs/ForgeStage.prefab");var fx=forge.GetComponent<ForgeAnimator>();var height=forge.GetComponent<LayoutElement>();height.minHeight=height.preferredHeight=310;for(int i=0;i<3;i++){Place((RectTransform)fx.Inputs[i].transform,new Vector2(.5f,.5f),new Vector2(94,94));((RectTransform)fx.Inputs[i].transform).anchoredPosition=new Vector2((i-1)*104,80);}Place((RectTransform)fx.Result.transform,new Vector2(.87f,.13f),new Vector2(58,70));fx.Message.fontSize=12;Place(fx.Message.rectTransform,new Vector2(.4f,.08f),new Vector2(240,34));PrefabUtility.SaveAsPrefabAsset(forge,Root+"Prefabs/ForgeStage.prefab");PrefabUtility.UnloadPrefabContents(forge);AssetDatabase.SaveAssets();Debug.Log("FORGE_COMPOSED_FUSION_READY 8 authored stepped-pixel frames; shared prefab");
  }
 }
